-- Структура таблицы `personal_information`
--

DROP TABLE IF EXISTS `personal_information`;
CREATE TABLE IF NOT EXISTS `personal_information` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id информации',
  `shtat_id` int(11) NOT NULL COMMENT 'id который привязывается к штатке',
  `job_assignment_date` date NOT NULL COMMENT 'Дата присвоения должности',
  `job_order_number` varchar(50) NOT NULL COMMENT 'номер приказа присвоения должности',
  `rank_assignment_date` date NOT NULL COMMENT 'дата присвоения звания',
  `rank_order_number` varchar(50) NOT NULL COMMENT 'номер приказа присвоения должности',
  `telephone_number` varchar(15) NOT NULL COMMENT 'номер телефона',
  `snills` varchar(50) NOT NULL COMMENT 'снилс',
  `passport_series` int(4) NOT NULL COMMENT 'Серия паспорта',
  `passport_numbers` int(6) NOT NULL COMMENT 'Номер паспорта',
  `passport_issued_by` varchar(50) NOT NULL COMMENT 'Кем выдан паспорт',
  `passport_photo` text NOT NULL DEFAULT '\'фото не загружено\'' COMMENT 'фото паспорта',
  `passport_date` date NOT NULL COMMENT 'Дата выдачи паспорта',
  `passport_unit _code` varchar(15) NOT NULL COMMENT 'Код подразделения паспорта',
  `military_card` varchar(50) NOT NULL COMMENT 'Военный билет',
  `military_card_photo` text DEFAULT NULL COMMENT 'Фото военного билета',
  `personal_number` varchar(15) NOT NULL COMMENT 'личный номер',
  `place_of_birth` varchar(100) NOT NULL COMMENT 'место рождения',
  `nationality` varchar(30) NOT NULL COMMENT 'национальность',
  `is_talent_pool` varchar(10) NOT NULL COMMENT 'В кадровом резерве?',
  `qualification_title` varchar(40) NOT NULL COMMENT 'Квалификационное звание',
  `participation_in_operations_id` int(11) DEFAULT NULL COMMENT ' Айди на участие в операциях',
  `history_of_work_id` int(11) DEFAULT NULL COMMENT 'видимо тут айди на историю работы будет потом',
  `admission` text NOT NULL COMMENT 'допуск',
  `abroad_id` int(11) DEFAULT NULL COMMENT 'айди за границей',
  `marital_status_id` int(11) DEFAULT NULL COMMENT 'семейное положение айди',
  `profile_photo` varchar(150) NOT NULL DEFAULT '#' COMMENT 'Фото в личном деле',
  `drivers_license` varchar(40) NOT NULL COMMENT 'Водительское удостоверение номер',
  `drivers_license_sdate` date NOT NULL COMMENT 'Водительское удостоверение дата с ',
  `drivers_license_edate` date NOT NULL COMMENT 'Водительское удостоверение дата по',
  `drivers_license_categories` varchar(20) NOT NULL COMMENT 'Водительское удостоверение категории',
  `drivers_license_photo` text DEFAULT NULL COMMENT 'Водительское удостоверение фото',
  `contract_date_start` date NOT NULL COMMENT 'Дата начала контракта',
  `contract_date_end` date NOT NULL COMMENT 'Дата конца контракта',
  `education_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

